from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0]); counts=Counter(x for row in grid for x in row); bg=counts.most_common(1)[0][0]
    out=[r[:] for r in grid]
    bars=[]
    # contiguous same-color non-background runs along each boundary
    for side in ('left','right','top','bottom'):
        n=h if side in ('left','right') else w
        for color in set(grid[r][c] for r in range(h) for c in range(w) if (c==0 if side=='left' else c==w-1 if side=='right' else r==0 if side=='top' else r==h-1) and grid[r][c]!=bg):
            i=0
            while i<n:
                r,c=(i,0) if side=='left' else (i,w-1) if side=='right' else (0,i) if side=='top' else (h-1,i)
                if grid[r][c]!=color: i+=1; continue
                start=i
                while i<n:
                    rr,cc=(i,0) if side=='left' else (i,w-1) if side=='right' else (0,i) if side=='top' else (h-1,i)
                    if grid[rr][cc]!=color: break
                    i+=1
                if i-start>=2: bars.append((side,color,start,i))
    barcells=set()
    for side,col,a,b in bars:
        for i in range(a,b): barcells.add((i,0) if side=='left' else (i,w-1) if side=='right' else (0,i) if side=='top' else (h-1,i))
    marks=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c]!=bg and (r,c) not in barcells]
    if not marks: return out
    mc=Counter(x[2] for x in marks).most_common(1)[0][0]
    marks=[(r,c) for r,c,col in marks if col==mc]
    # current pattern: equal-length opposing vertical edge bars, with markers in one bar's span
    left=[b for b in bars if b[0]=='left']; right=[b for b in bars if b[0]=='right']
    pair=None
    for L in left:
        for R in right:
            if L[3]-L[2]==R[3]-R[2]: pair=(L,R); break
        if pair: break
    if pair:
        L,R=pair
        source=None
        if any(L[2]<=r<L[3] for r,c in marks): source=L; other=R
        elif any(R[2]<=r<R[3] for r,c in marks): source=R; other=L
        if source:
            ss,sc,sa,sb=source; os,oc,oa,ob=other
            for r,c in marks:
                if not sa<=r<sb: continue
                # fill inward from the source edge until the marker; recolor marker 4
                if ss=='left':
                    for x in range(1,c): out[r][x]=mc
                else:
                    for x in range(w-2,c,-1): out[r][x]=mc
                out[r][c]=4
                # corresponding row in opposite bar: fill across, preserving rail cells
                rr=oa+(r-sa)
                for x in range(w):
                    if (rr,x) not in barcells: out[rr][x]=mc
    return out

