def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find straight, non-background runs on the four borders.
    bars = []  # (side, color, start, end), end exclusive
    for side in ("left", "right", "top", "bottom"):
        n = h if side in ("left", "right") else w

        def border_cell(i):
            if side == "left":
                return grid[i][0]
            if side == "right":
                return grid[i][w - 1]
            if side == "top":
                return grid[0][i]
            return grid[h - 1][i]

        i = 0
        while i < n:
            color = border_cell(i)
            if color == bg:
                i += 1
                continue
            start = i
            while i < n and border_cell(i) == color:
                i += 1
            if i - start >= 2:
                bars.append((side, color, start, i))

    # The two equal-length bars on opposite edges form the ray guides.
    pair = None
    for a in bars:
        for b in bars:
            if a[0] == "left" and b[0] == "right" and a[1] == b[1] and a[3] - a[2] == b[3] - b[2]:
                pair = (a, b)
                break
            if a[0] == "top" and b[0] == "bottom" and a[1] == b[1] and a[3] - a[2] == b[3] - b[2]:
                pair = (a, b)
                break
        if pair:
            break
    if pair is None:
        return out

    a, b = pair
    bar_cells = set()
    for side, _, start, end in pair:
        for k in range(start, end):
            if side == "left":
                bar_cells.add((k, 0))
            elif side == "right":
                bar_cells.add((k, w - 1))
            elif side == "top":
                bar_cells.add((0, k))
            else:
                bar_cells.add((h - 1, k))

    # Each isolated non-background marker selects a position along one bar;
    # corresponding rays are launched from both paired bars.
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in bar_cells]

    def cast(side, k, color, marker=None):
        if side == "left":
            coords = [(k, c) for c in range(1, w)]
        elif side == "right":
            coords = [(k, c) for c in range(w - 2, -1, -1)]
        elif side == "top":
            coords = [(r, k) for r in range(1, h)]
        else:  # bottom
            coords = [(r, k) for r in range(h - 2, -1, -1)]
        for r, c in coords:
            if marker == (r, c):
                out[r][c] = 4
                break
            if grid[r][c] != bg:
                # A marker intercepts a beam; bars and other objects remain intact.
                if (r, c) not in bar_cells and grid[r][c] != bg:
                    out[r][c] = 4
                break
            out[r][c] = color

    for r, c, color in markers:
        if a[0] in ("left", "right"):
            along = r
            if a[2] <= along < a[3]:
                source, target = a, b
            elif b[2] <= along < b[3]:
                source, target = b, a
            else:
                continue
            offset = along - source[2]
            target_k = target[2] + offset
            cast(source[0], along, color, (r, c))
            cast(target[0], target_k, color)
        else:
            along = c
            if a[2] <= along < a[3]:
                source, target = a, b
            elif b[2] <= along < b[3]:
                source, target = b, a
            else:
                continue
            offset = along - source[2]
            target_k = target[2] + offset
            cast(source[0], along, color, (r, c))
            cast(target[0], target_k, color)

    return out


